function e(value) { return escapeHtml(value); }
function n(value) { return Number(value || 0); }
function pct(numerator, denominator) { return denominator ? Math.round((Number(numerator || 0) / Number(denominator)) * 100) : 0; }

function csrfInput(csrfToken) {
  return `<input type="hidden" name="csrf" value="${e(csrfToken)}">`;
}

function messageAlert(message) {
  if (!message?.text) return '';
  const type = ['success', 'error', 'warning', 'info'].includes(message.type) ? message.type : 'info';
  return `<div class="alert ${type}" role="status">${e(message.text)}</div>`;
}

function isActive(pathname, target, exact = false) {
  return exact ? pathname === target : pathname === target || pathname.startsWith(`${target}/`);
}

function navLink({ href, label, icon, active, count }) {
  return `<li><a class="nav-link ${active ? 'active' : ''}" href="${href}"><span class="nav-icon" aria-hidden="true">${e(icon)}</span><span>${e(label)}</span>${count ? `<span class="nav-count">${e(count)}</span>` : '<span></span>'}</a></li>`;
}

