function statusBadge(status, dueAt = null) {
  const overdue = dueAt && new Date(dueAt) < new Date() && status !== 'completed';
  if (overdue) return '<span class="badge status-overdue">Overdue</span>';
  const label = String(status || 'assigned').replaceAll('_', ' ');
  return `<span class="badge status-${e(status)}">${e(label)}</span>`;
}

function dueText(dueAt) {
  if (!dueAt) return 'No due date';
  const overdue = new Date(dueAt) < new Date();
  return `${overdue ? 'Was due' : 'Due'} ${formatDate(dueAt, { short: true })}`;
}

function courseProgress(assignment) {
  if (assignment.status === 'completed') return 100;
  if (assignment.delivery_type === 'legacy') return assignment.status === 'in_progress' ? 20 : 0;
  const total = (assignment.lessons || []).length;
  const complete = (assignment.progress?.lessons || []).length;
  return total ? Math.round((complete / total) * 80) : 0;
}

