function learningPage({ assignments }) {
  const open = assignments.filter(a => a.status !== 'completed');
  const completed = assignments.filter(a => a.status === 'completed');
  return `<div class="page-heading"><div><h1>My Learning</h1><p>Assigned courses, due dates, progress, scores, and renewal status.</p></div><div class="page-actions"><a class="btn btn-light" href="/library">Browse course library</a></div></div>
<div class="stat-grid"><div class="stat-card"><strong>${assignments.length}</strong><span>Total Assigned</span></div><div class="stat-card yellow"><strong>${open.length}</strong><span>Open</span></div><div class="stat-card green"><strong>${completed.length}</strong><span>Completed</span></div><div class="stat-card red"><strong>${open.filter(a => a.due_at && new Date(a.due_at)<new Date()).length}</strong><span>Overdue</span></div></div>
<section><h2 class="sr-only">Open courses</h2>${open.length ? `<div class="course-grid">${open.map(courseAssignmentCard).join('')}</div>` : `<div class="card empty-state"><div class="empty-icon">✓</div><strong>All assigned courses are complete</strong><p>Your completed records are shown below.</p></div>`}</section>
${completed.length ? `<div class="page-heading" style="margin-top:26px"><div><h1 style="font-size:1.45rem">Completed Training</h1><p>Completed courses remain available with their score and certificate.</p></div></div><div class="course-grid">${completed.map(courseAssignmentCard).join('')}</div>` : ''}`;
}

function courseAssignmentCard(a) {
  const progress = courseProgress(a);
  const expired = a.expires_at && new Date(a.expires_at) < new Date();
  return `<article class="course-card" data-category="${e(a.category)}"><div class="inline"><span class="badge">${e(a.category)}</span>${statusBadge(expired ? 'overdue' : a.status, a.due_at)}${a.required ? '<span class="badge red">Required</span>' : ''}</div><h2>${e(a.title)}</h2><p>${e(a.description || '')}</p><div class="course-meta"><span>${n(a.estimated_minutes)} min</span><span>${n(a.points)} points</span><span>Pass ${n(a.passing_score)}%</span>${a.score !== null ? `<span>Score ${n(a.score)}%</span>` : ''}</div><div class="course-progress"><div class="progress-label"><span>${a.status === 'completed' ? `Completed ${formatDate(a.completed_at,{short:true})}` : dueText(a.due_at)}</span><span>${progress}%</span></div><div class="progress-track"><div class="progress-fill ${a.status === 'completed' ? 'green' : ''}" data-progress="${progress}"></div></div></div><div class="card-footer"><span class="small muted">${a.delivery_type === 'legacy' ? 'Full interactive module' : `${(a.progress?.lessons||[]).length}/${(a.lessons||[]).length || '—'} lessons`}</span><a class="btn ${a.status === 'completed' ? 'btn-light' : 'btn-primary'} btn-small" href="/learn/${a.id}">${a.status === 'completed' ? 'Review' : a.status === 'assigned' ? 'Start course' : 'Continue'}</a></div></article>`;
}

